fn is_nested(s: Vec<i8>) -> bool {
    // If array length < 4, impossible to find four such indices
    if s.len() < 4 {
        return false;
    }

    // We want to find indices i < j < k < l such that:
    // s[i] = 0, s[j] = 0, s[k] = 1, s[l] = 1

    // We'll try to find the pattern step-wise using a state machine approach.
    // State meanings:
    // 0: haven't found any zeros yet
    // 1: found first zero
    // 2: found second zero
    // 3: found first one
    // 4: found second one -> success

    let mut state = 0;

    for &val in &s {
        match state {
            0 => {
                if val == 0 {
                    state = 1;
                }
            }
            1 => {
                if val == 0 {
                    state = 2;
                }
            }
            2 => {
                if val == 1 {
                    state = 3;
                }
            }
            3 => {
                if val == 1 {
                    // Found the second 1 after two zeros
                    state = 4;
                    break;
                }
            }
            4 => break, // already found
            _ => unreachable!(),
        }
    }

    state == 4
}